import { WebWorkerMLCEngineHandler } from "@mlc-ai/web-llm";

// This handler hooks into the WebLLM engine and communicates with the main thread
const handler = new WebWorkerMLCEngineHandler();

self.addEventListener("message", (event) => {
    try {
        console.log("Worker received UUID:", event.data.uuid, "Kind:", event.data.kind);
        handler.onmessage(event);
    } catch (err) {
        console.error("CRITICAL WORKER ERROR:", err);
        console.error("DETAILED WORKER FAILURE:", err);
        console.group("Error Details");
        console.log("Message:", err.message);
        console.log("Stack:", err.stack);
        console.groupEnd();// This will show the real error in the console!
        self.postMessage({
            uuid: event.data.uuid,
            kind: "return",
            result: { error: err.message }
        });
    }
});
